using System.Collections.Immutable;
using Client.Workspace.Domain;

namespace Client.Compilation;

/// <summary>Opaque fresh request id. Generated by the trusted context factory,
/// never parsed from an untrusted echo to construct authority. Worker transport
/// later correlates responses by this id; it is not proof a worker ran.</summary>
public readonly record struct CompileRequestId(Guid Value)
{
    public static CompileRequestId New() => new(Guid.NewGuid());
    public static CompileRequestId Parse(Guid value) => new(value);
    public override string ToString() => Value.ToString("N");
}

/// <summary>Immutable output-side descriptor (requested format or native adapter
/// identity). Metadata only: NOT a capability approval, provisioning receipt or
/// installed-engine claim. Hash is optional; when present it must be a valid
/// lowercase 64-hex SHA-256.</summary>
public sealed record CompileOutputDescriptor(string Id, string Version, SHA256? Hash);

/// <summary>Terminal outcome of a compile attempt. Only <see cref="Succeeded"/>
/// may carry an accepted artifact. Non-success outcomes never own a payload.</summary>
public enum CompileOutputStatus { Succeeded, Failed, Cancelled, TimedOut, Unsupported }

/// <summary>Bounded typed failures for the output boundary. Fixed values, never
/// used to echo raw exception text, source paths, secrets or document content.</summary>
public enum CompileOutputIssue
{
    InvalidBudget, InvalidStatus, InvalidMetadata, InvalidHash, MalformedUnicode, Overflow,
    MissingPayload, PayloadOnNonSuccess, LengthMismatch, HashMismatch,
    OverPayloadBudget, OverMetadataBudget, OverDiagnosticCount,
    RequestMismatch, SnapshotMismatch, DigestMismatch, EpochMismatch,
    FormatMismatch, AdapterMismatch, MappingMismatch,
    OverSourceMapPayloadBudget, SourceMapLengthMismatch, SourceMapHashMismatch
}

/// <summary>Untrusted diagnostic/log metadata: plain data only. Never executable
/// HTML and never a trusted source span. Code is a stable short identifier;
/// SafeMessage is a bounded control-free strict UTF-8 string (may be empty).</summary>
public sealed record CompileDiagnosticEntry(string Code, string SafeMessage);

/// <summary>Opaque owned source-mapping identity: exact hash/length only. No
/// navigation promise is made or implied by owning this identity.</summary>
public sealed record CompileSourceMappingIdentity(SHA256 Hash, long ByteLength);

/// <summary>Deterministic artifact content identity, separate from request/
/// session/worker freshness. The digest is SHA-256 of the
/// <c>overclone-compilation-artifact-v1</c> encoding of the complete input content
/// digest, output length/hash and any explicit format/adapter/mapping metadata
/// actually modeled. Equal content may share identity with distinct request ids.</summary>
public sealed record CompileArtifactContentIdentity(
    SHA256 Digest, SHA256 InputContentDigest, long OutputLength, SHA256 OutputHash,
    CompileOutputDescriptor? OutputFormat, CompileOutputDescriptor? OutputAdapter,
    CompileSourceMappingIdentity? SourceMapping);

/// <summary>Explicit caller limits for accepting an untrusted output envelope.
/// Zero is never unlimited. All fields must be positive and within Array.MaxLength;
/// source-map bytes additionally cannot exceed the fixed producer limit.</summary>
public sealed record CompileOutputBudget(int MaxPayloadBytes, int MaxMetadataBytes,
    int MaxDiagnostics, int MaxDiagnosticCodeBytes, int MaxDiagnosticMessageBytes, int MaxLogBytes)
{
    public const int SourceMapPayloadByteLimit = 1_048_575;
    /// <summary>Independent byte cap for optional opaque uncompressed SyncTeX v1
    /// output. Does not enlarge the PDF or metadata budgets. May only be reduced
    /// from the fixed producer limit; zero is not an unlimited/disabled sentinel.</summary>
    public int MaxSourceMapPayloadBytes { get; init; } = SourceMapPayloadByteLimit;

    public bool IsValid => MaxSourceMapPayloadBytes > 0 && MaxSourceMapPayloadBytes <= SourceMapPayloadByteLimit
        && MaxPayloadBytes > 0 && MaxPayloadBytes <= Array.MaxLength
        && MaxMetadataBytes > 0 && MaxMetadataBytes <= Array.MaxLength
        && MaxDiagnostics > 0 && MaxDiagnostics <= Array.MaxLength
        && MaxDiagnosticCodeBytes > 0 && MaxDiagnosticCodeBytes <= Array.MaxLength
        && MaxDiagnosticMessageBytes > 0 && MaxDiagnosticMessageBytes <= Array.MaxLength
        && MaxLogBytes > 0 && MaxLogBytes <= Array.MaxLength;
}

/// <summary>Untrusted envelope input as a worker would echo it. Lists may alias
/// caller storage; <see cref="CompileOutputEnvelope.Create"/> validates, bounds
/// and privately owns every field before constructing an envelope.</summary>
public sealed record CompileOutputEnvelopeInput
{
    public required CompileRequestId RequestId { get; init; }
    public required CompilationSnapshotIdentity SnapshotIdentity { get; init; }
    public required SHA256 InputContentDigest { get; init; }
    public required long WorkerEpoch { get; init; }
    public required CompileOutputStatus Status { get; init; }
    public byte[]? Payload { get; init; }
    public long ClaimedLength { get; init; }
    public SHA256? ClaimedHash { get; init; }
    public CompileOutputDescriptor? OutputFormat { get; init; }
    public CompileOutputDescriptor? OutputAdapter { get; init; }
    public CompileSourceMappingIdentity? SourceMapping { get; init; }
    /// <summary>Optional opaque uncompressed SyncTeX v1 bytes from the final
    /// successful native pass alongside its PDF. Never parsed here. Nonempty
    /// bytes must match SourceMapping exactly; null/empty on success means no
    /// owned map. Any non-null value on non-success is refused.</summary>
    public byte[]? SourceMapPayload { get; init; }
    public IReadOnlyList<CompileDiagnosticEntry>? Diagnostics { get; init; }
    public string? LogText { get; init; }
}

public sealed record CompileRequestContextCreation(CompileRequestContext? Context, CompileOutputIssue? Failure);
public sealed record CompileOutputEnvelopeCreation(CompileOutputEnvelope? Envelope, CompileOutputIssue? Failure);
public sealed record CompileOutputAcceptance(AcceptedCompileOutput? Output, CompileOutputIssue? Failure);
